<?php declare(strict_types=1); namespace Modules\PromptEngine\Services\ImageProviders; abstract class AbstractPromptProvider { protected function base(array $c): string { $a=$c['analysis'];$p=$c['plan']; return "Create a professional {$c['style']} educational infographic about the exact Chinese character {$a['character']}. Preserve that glyph exactly. Meaning: {$a['meaning_en']} Composition: ".json_encode($p['composition'],JSON_UNESCAPED_UNICODE).'. Main visual: '.$p['main_subject'].'. Typography: '.json_encode($p['typography'],JSON_UNESCAPED_UNICODE).'. Palette: '.implode(', ',$p['color_palette']).'. Lighting: '.$p['lighting']['description'].'. Materials: '.implode(', ',$p['materials']).'. Aspect ratio '.$c['aspect_ratio'].'. '; } protected function avoid(array $c): string { return implode(', ',$c['plan']['negative_constraints']); } }
